\section{Related Work}
\label{sec:related-work}

\looseness=-1
\paragraph{Self-consistency and ensemble theory.}
Self-consistency (SC) selects the majority answer across chain-of-thought traces \citep{wang2023sc}, with extensions for free-form generation \citep{chen2024usc}, confidence weighting \citep{taubenfeld2025cisc}, diverse prompting \citep{li2023diverse}, and reasoning-aware filtering \citep{wan2024rasc, toh2024notallvotes, kim2026reasc}. SC gains plateau early \citep{loo2025reevaluating, byerly2025selfconsistency}. The Condorcet Jury Theorem \citep{condorcet1785} guarantees majority-vote convergence under independence; ensemble theory \citep{dietterich2000ensemble, krogh1994neural} requires error diversity. \citet{ladha1992correlated} show correlated voters reduce effective ensemble size; our $K_\text{eff}$ adapts Fleiss' $\kappa$ from diversity metrics \citep{kuncheva2003measures, brown2005diversity} to quantify this (\S\ref{sec:pipeline}). \citet{kim2025correlated} demonstrate correlated LLM errors; \citet{kuai2026independent} propose cross-model independence auditing.

\looseness=-1
\paragraph{Neuro-symbolic reasoning.}
Three paradigms exist: \emph{specification-generation} \citep{pan2023logiclm, olausson2023linc, ye2024satlm} and \emph{program-generation} \citep{gao2023pal, chen2023program, lyu2023faithful} formalize before answer generation; \emph{trace-extraction} (this work) operates post-hoc, inheriting confirmation bias (\S\ref{sec:confirmation-bias}). Recent work extends symbolic planning and verified reasoning \citep{ryu2025clover, xu2026dylos, xu2025aristotle, pei2025fover, singh2026verge, luo2025logicagent, miya2025eidoku}; \citet{amonkar2025realitycheck} show formalization quality degrades with complexity; \citet{chan2026position} argue logical soundness alone is unreliable. Prior studies note high formalization error rates but treat them as quality problems; we show they are \emph{systematically biased} toward the model's answer (Observation~1). This reveals a mechanism underlying \citet{huang2024selfcorrect}'s finding that LLMs cannot self-correct without external feedback: we formalize the failure via the $M{\to}T{\to}(A,C)$ generation structure and provide three lightweight diagnostics that predict failure modes before deployment. Our symbolic confirmation bias (SCB) is distinct from CoT-level confirmation bias \citep{wan2025unveiling, turpin2023language, jhaveri2026failing}: CoT bias concerns trace-level faithfulness, while SCB shows the \emph{collection} of self-extracted constraints mirrors the answer distribution even when individual traces are locally faithful.

\looseness=-1
\paragraph{Verification and test-time scaling.}
Scaling test-time compute via additional traces \citep{snell2025scaling}, structured search \citep{yao2023tree}, or extended reasoning \citep{guo2025deepseekr1, qwen2024qwq} faces the same correlation challenge when traces share a model's biases. Self-verification methods, including multi-agent debate \citep{liang2023encouraging, du2023improving}, self-evaluation \citep{xie2023selfevaluation, weng2023selfverification, madaan2023selfrefine, dhuliawala2023chainofverification}, iterative improvement \citep{shinn2023reflexion, zhou2023lats}, tool-augmented critique \citep{gou2024critic}, formal CoT verification \citep{feng2025vericot, chen2025sets}, and multi-agent verification \citep{lifshitz2025mav}, report gains but none tests self-extracted constraints under formal solvers \citep[cf.][]{kamoi2024selfcorrect}; the bottleneck lies in constraint extraction, not verification (\S\ref{sec:confirmation-bias}). Trained verifiers can escape this bottleneck through external reward signals: outcome and process reward models \citep{cobbe2021gsm8k, lightman2024prm, wang2024mathshepherd}, discriminator-guided decoding \citep{khalifa2023grace}, RL-based self-verification \citep{zeng2025s2r}, dual preference optimization \citep{dupo2025}, and execution-based filtering \citep{li2022alphacode, chen2023codet}. These operate outside Observation~1's pipeline and may overcome the information-theoretic bottleneck. The failure modes differ: SICA's bottleneck is extraction fidelity, whereas PRM/ORM's is reward model generalization \citep{wang2024mathshepherd}.

\section{Experiments}
\label{sec:results}
\label{sec:main-results}

\begin{figure*}[t]
\centering
\includegraphics[width=0.7\textwidth]{f2_regime_scatter_v2}
\caption{SICA $\Delta$ (pp) vs.\ SC baseline accuracy. Color encodes model family; shape encodes dataset (\scalebox{0.7}{$\blacksquare$}\,PW, \scalebox{0.7}{$\blacktriangle$}\,FOLIO, \scalebox{0.7}{$\bullet$}\,LogiQA). Circled points are significant ($p < .05$). The grey band marks the $\pm 2$\,pp equivalence zone; connected points show seed-level variance for Mistral-7B$\times$FOLIO. Three regimes emerge: Type~C (error amplification), intermediate, and Type~A (confirmation bias). No condition escapes the equivalence band with a positive effect.}
\label{fig:regime-scatter}
\end{figure*}

\subsection{Experimental Setup}
\label{sec:exp-setup}

\looseness=-1
\paragraph{Models.} Qwen2.5-14B-Instruct, Qwen2.5-7B-Instruct, Qwen3-14B (non-thinking mode)~\citep{yang2024qwen25}, Mistral-7B-Instruct-v0.3~\citep{jiang2023mistral}, LLaMA-3.1-8B-Instruct~\citep{dubey2024llama3}, and QwQ-32B~\citep{qwen2024qwq} (7B--32B). We also evaluate the universality of symbolic confirmation bias on six additional models: gpt-4o uses self-extraction via API; four frontier models (gpt-4.1, gpt-5.5, o3, Gemini-2.5-Pro) use cross-model extraction where Mistral-7B extracts constraints from target traces; DeepSeek-R1-Distill-Qwen-8B likewise uses Mistral-7B cross-extraction (Appendix Table~\ref{tab:frontier-scb}).

\paragraph{Datasets.} FOLIO~\citep{han2022folio} ($n{=}204$, gold logical annotations), ProofWriter depth-5~\citep{tafjord2021proofwriter} ($n{=}600$), LogiQA~\citep{liu2020logiqa} ($n{=}200$), StrategyQA~\citep{geva2021strategyqa} ($n{=}200$). GSM8K ($n{=}30$) and AIME 2024 ($n{=}22$) probe the degenerate regime ($C_0 < 5\%$).

\paragraph{Parameters.} $K{=}12$ traces at $T{=}0.7$, extraction at $T_{\text{ext}}{=}0.3$, $\alpha{=}0.5$, Z3 timeout 10s (K-sensitivity and extraction-temperature analysis in Appendix~\ref{app:sensitivity}). McNemar exact test ($\alpha{=}0.05$); 95\% bootstrap CIs ($10{,}000$ resamples; Appendix~\ref{app:bootstrap}) for $n \geq 200$. SICA incurs $4.5{\times}$ SC wall-clock; extraction accounts for 76\% of overhead.

\subsection{Main Results}

\looseness=-1 Table~\ref{tab:main_results} reports accuracy across all non-degenerate self-extraction conditions sorted by SC baseline. Two confirmatory conditions show significant degradation after Benjamini--Hochberg (BH) FDR control ($m{=}6$; multi-seed aggregates and extensions are exploratory): Mistral-7B on ProofWriter ($-2.83$\,pp, raw $p = 0.014$, adj.\ $p = 0.042$) and Qwen2.5-14B on ProofWriter ($-2.50$\,pp, raw $p = 0.011$, adj.\ $p = 0.042$). No condition shows a significant positive effect. An aggregate sign test yields 8 positive and 7 negative $\Delta$ values ($p = 1.00$, two-sided). When SICA and SC disagree, SC selects the correct answer $2.6\times$ more often (139 vs.\ 53 across conditions); constraint-based reweighting thus introduces noise rather than corrective signal (representative cases in Appendix~\ref{app:case-studies}; Appendix~\ref{app:subpopulation}).

\begin{figure*}[t]
\centering
\includegraphics[width=\textwidth]{figures/fig3_causal_dag_v11.pdf}
\caption{Causal DAG of the self-extraction pipeline. Traces $T$ produce both answers $A$ and constraints $C$; under degeneration (Observation~1), $C$ is determined by $A$ (dashed arrow), yielding $I(C;Y) \leq I(A;Y)$.}
\label{fig:causal-dag}
\end{figure*}

\looseness=-1 Figure~\ref{fig:regime-scatter} reveals regime structure across SC baselines. Three regimes emerge: Type~C (SC $\leq 40\%$), where low accuracy causes error amplification; an intermediate band (50--60\%), containing the only positive trends; and Type~A (SC $\geq 60\%$), where symbolic confirmation bias dominates. Fleiss' $\kappa$ ranges from 0.19 to 0.82, yielding $K_{\text{eff}} = 1.20\text{--}3.94$ at $K = 12$ (Table~\ref{tab:independence}; Appendix~\ref{app:cross-model-kappa}). Seed-level noise is substantial: across three Mistral-7B seeds, $\Delta$ ranges from $+2.94$ to $-2.45$\,pp despite $\kappa \in [0.45, 0.46]$. We trace the mechanism in \S\ref{sec:analysis}.

\looseness=-1 We use TOST equivalence tests \citep{lakens2017equivalence} with margin $\pm 2$\,pp, justified on four grounds: (1)~on FOLIO ($n{=}204$), $\pm$2\,pp corresponds to ${\sim}$4 problems, near single-item influence; (2)~multi-seed SC variability $\sigma_{\text{SC}} = 1.67$--$2.51$\,pp on FOLIO, with $\sigma_\Delta$ up to 2.70\,pp (Table~\ref{tab:multi-seed}), placing $\pm$2\,pp within natural noise; (3)~the observed $|\Delta|$ median across 11 conditions is 1.47\,pp, so $\pm$2\,pp captures the central tendency; (4)~sensitivity analysis confirms $\pm$2\,pp as the narrowest discriminating window ($\pm$1\,pp: zero conditions pass; $\pm$3\,pp: all pass; Appendix~\ref{app:tost}). Four of 11 conditions pass TOST equivalence (minimum detectable effect (MDE) $\leq 2$\,pp); the remaining seven are underpowered (MDE $4.6$--$4.8$\,pp) but provide consistent directional evidence ($|\Delta| \leq 4.41$\,pp, none significant; Appendix~\ref{app:power}). Multi-seed replication: mean $\Delta = +0.16 \pm 2.70$\,pp across three Mistral-7B seeds (Table~\ref{tab:multi-seed}); four Qwen2.5-14B seeds yield $\Delta \in [0.00, -2.01]$\,pp; four Qwen3-14B seeds yield $\Delta = +0.92 \pm 1.14$\,pp (n.s.; Appendix~\ref{app:single-trace}). Oracle controls confirm the MAX-SAT mechanism is sound ($+29.90$/$+13.73$\,pp FOLIO, $+17.17$\,pp ProofWriter; $p < 0.001$), yet self-extraction captures only ${\sim}12\%$ of this ceiling (Appendix~\ref{app:oracle}; Appendix~\ref{app:pw-oracle-subtype}).
